html, body { margin: 0; height: 100%; background: #0F172A; }

.wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  font-family: system-ui, -apple-system, sans-serif;
}

.status {
  flex: 0 0 auto;
  padding: 6px 10px;
  font-size: 12px;
  line-height: 1.4;
  color: #94A3B8;
  background: #1E293B;
  border-bottom: 1px solid #334155;
}
.status.ok   { color: #6FCFA4; }
.status.warn { color: #E5B562; }
.status.err  { color: #F08A8A; }

/* AG Studio sizes itself to its container, so the container needs a real height. */
#studio-root { flex: 1 1 auto; min-height: 0; }

