// AG Studio inside an Appsmith custom widget.
// The UMD bundle (~5MB) exposes window.agStudio and carries its own copies of
// ag-grid-enterprise and ag-charts-enterprise, so nothing else is loaded here.
var api = null;
var appliedKey = '';
var lastDataSig = '';
var lastStateKey = -1;

function el(id) { return document.getElementById(id); }

function setStatus(text, kind) {
  var n = el('studio-status');
  if (!n) return;
  n.className = 'status ' + (kind || '');
  n.textContent = text;
}

function rowsOf(model) {
  return (model && Array.isArray(model.rows)) ? model.rows : [];
}

// Cheap signature so we only rebuild Studio when the dataset actually changes.
function dataSignature(model) {
  var rows = rowsOf(model);
  return [model && model.customerId, rows.length, rows.length ? Object.keys(rows[0]).join(',') : ''].join('|');
}

function applyLicense(model) {
  var key = (model && model.licenseKey ? String(model.licenseKey) : '').trim();
  if (!key || key === appliedKey) return;
  if (!window.agStudio || !agStudio.AgStudioLicenseManager) return;
  try {
    agStudio.AgStudioLicenseManager.setLicenseKey(key);
    appliedKey = key;
  } catch (e) {
    console.warn('AG Studio setLicenseKey failed', e);
  }
}

// Reports what AG Studio thinks of the supplied key. getLicenseDetails is marked
// internal, so any failure here is non-fatal — Studio still renders, watermarked.
function describeLicense(model) {
  var key = (model && model.licenseKey ? String(model.licenseKey) : '').trim();
  if (!key) return 'no licence key set — running unlicensed (watermarked)';
  try {
    var d = agStudio.AgStudioLicenseManager.getLicenseDetails(key, new Set());
    if (!d) return 'licence key applied';
    if (d.valid && !d.expired) {
      return 'licence OK' + (d.isTrial ? ' (trial)' : '') + (d.expiry ? ', expires ' + d.expiry : '');
    }
    if (d.incorrectLicenseType) {
      return 'WRONG LICENCE TYPE — supplied ' + (d.suppliedLicenseType || 'unknown') +
             ', Studio needs ' + (d.currentLicenseType || 'STUDIO-*');
    }
    if (d.expired) return 'licence expired' + (d.expiry ? ' on ' + d.expiry : '');
    return 'licence not valid for AG Studio';
  } catch (e) {
    return 'licence key applied (could not verify)';
  }
}

function buildStudio(model) {
  var root = el('studio-root');
  if (!root) return;
  var rows = rowsOf(model);

  if (api && typeof api.destroy === 'function') {
    try { api.destroy(); } catch (e) { /* already gone */ }
  }
  api = null;
  root.innerHTML = '';

  if (rows.length === 0) {
    setStatus('No rows returned for this customer.', 'warn');
    return;
  }

  var props = {
    mode: 'edit',
    // Fields are inferred from the row data when not supplied.
    data: {
      sources: [{
        id: 'monthly_usage',
        name: (model && model.customerName ? model.customerName + ' — ' : '') + 'Monthly Usage',
        description: 'Monthly billed usage and charges per location, utility and vendor.',
        data: rows
      }]
    },
    dataOptions: { maxExportRows: -1 },
    onStudioReady: function () {
      setStatus(rows.length.toLocaleString() + ' rows loaded · ' + describeLicense(model), 'ok');
    },
    onErrorRaised: function (ev) {
      console.error('AG Studio error', ev);
      setStatus('Studio error: ' + ((ev && ev.message) || 'see console'), 'err');
    },
    // Surface report state so a Save button can persist it via storeValue.
    onStateUpdated: function (ev) {
      if (!appsmith.updateModel) return;
      try {
        appsmith.updateModel({ reportState: (ev && ev.state) || (api && api.getState && api.getState()) || null });
      } catch (e) { /* non-fatal */ }
    }
  };

  if (model && model.savedState) props.initialState = model.savedState;

  try {
    api = agStudio.createStudio(root, props);
    setStatus('Starting AG Studio…');
  } catch (e) {
    console.error(e);
    setStatus('createStudio failed: ' + (e && e.message), 'err');
  }
}

function render(model) {
  if (!window.agStudio || !agStudio.createStudio) {
    setStatus('AG Studio bundle did not load — check the CDN script tag.', 'err');
    return;
  }
  applyLicense(model);

  var sig = dataSignature(model);
  var stateKey = Number(model && model.stateKey) || 0;
  if (sig === lastDataSig && stateKey === lastStateKey) return;
  lastDataSig = sig;
  lastStateKey = stateKey;
  buildStudio(model);
}

// The bundle is large; poll briefly for the global before first render.
function whenReady(model, tries) {
  if (window.agStudio && agStudio.createStudio) { render(model); return; }
  if (tries <= 0) {
    setStatus('Timed out waiting for the AG Studio bundle (~5MB). Reload the page.', 'err');
    return;
  }
  setStatus('Loading AG Studio bundle…');
  setTimeout(function () { whenReady(model, tries - 1); }, 250);
}

appsmith.onReady(function () {
  whenReady(appsmith.model, 160);

  appsmith.onModelChange(function (model) {
    if (window.agStudio && agStudio.createStudio) render(model);
  });
});

